import React, { useEffect, useState } from 'react'

function RandomPokemonText() {
  const DAILY_KEY = 'dailyPokemon'
  const [imagePath, setImagePath] = useState('')

  useEffect(() => {
    // Retrieve the Pokémon image from localStorage
    const storedData = JSON.parse(localStorage.getItem(DAILY_KEY))
    if (storedData) {
      setImagePath(storedData.imagePath)
    }
  }, [])

  return (
    <div className='p-8 text-center'>
      {imagePath && (
        <div>
          <p className='text-lg font-semibold text-green-light'>
            Today's Pokémon:{' '}
            {imagePath
              .replace('/Pictures/', '')
              .replace('.png', '')
              .replace('_', ' ')}
          </p>
        </div>
      )}
    </div>
  )
}

export default RandomPokemonText
